import{_ as d,o as a,c as e,ak as o}from"./chunks/framework.DKi5cyCJ.js";const b=JSON.parse('{"title":"CAN 总线","description":"干线拓扑、CAN ID、帧类型、经典 CAN 与 CAN FD、采样点","frontmatter":{"title":"CAN 总线","description":"干线拓扑、CAN ID、帧类型、经典 CAN 与 CAN FD、采样点","date":"2026-10-20T00:00:00.000Z"},"headers":[],"relativePath":"pages/blog/2026-10-20-CAN总线.md","filePath":"pages/blog/2026-10-20-CAN总线.md"}'),l={name:"pages/blog/2026-10-20-CAN总线.md"};function s(i,t,r,c,n,h){return a(),e("div",null,[...t[0]||(t[0]=[o(`<h1 id="can-标识符、拓扑、帧与位时序" tabindex="-1">CAN：标识符、拓扑、帧与位时序 <a class="header-anchor" href="#can-标识符、拓扑、帧与位时序" aria-label="Permalink to &quot;CAN：标识符、拓扑、帧与位时序&quot;">​</a></h1><blockquote><p>系列目录：<a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">嵌入式驱动面试手册</a> · 动态演示：<a href="/demos/can-timing.html" target="_blank">时序</a> · <a href="/demos/can-topo.html" target="_blank">拓扑</a></p></blockquote><div class="blog-demo-frame"><iframe src="/demos/can-timing.html?embed=1" title="CAN 时序动态演示" loading="lazy"></iframe></div><p>高速 CAN（ISO 11898-2）是多主差分总线。逻辑 0 是显性，逻辑 1 是隐性。任一节点发显性，总线就是显性。ID 从高位开始比，先发出 0 的节点获胜，所以 ID 越小优先级越高。</p><table tabindex="0"><thead><tr><th>状态</th><th>逻辑</th><th>CANH</th><th>CANL</th><th>差分</th></tr></thead><tbody><tr><td>隐性</td><td>1</td><td>约 2.5 V</td><td>约 2.5 V</td><td>约 0 V</td></tr><tr><td>显性</td><td>0</td><td>约 3.5 V</td><td>约 1.5 V</td><td>约 2 V</td></tr></tbody></table><p>控制器的 TX/RX 是单端逻辑，TJA1050、TJA1042 一类收发器才变成差分。</p><h2 id="一主多从怎么接线" tabindex="-1">一主多从怎么接线 <a class="header-anchor" href="#一主多从怎么接线" aria-label="Permalink to &quot;一主多从怎么接线&quot;">​</a></h2><p>协议是多主。一主多从只表示应用层谁发命令、谁报状态。主控也是干线上的一个节点。</p><div class="blog-flow"><div class="blog-flow-row"><div class="blog-flow-node">120 Ω<br><small>主控板</small></div><div class="blog-flow-arrow">干线</div><div class="blog-flow-node accent">主控</div><div class="blog-flow-arrow">短支线</div><div class="blog-flow-node">从机</div><div class="blog-flow-arrow">短支线</div><div class="blog-flow-node">从机</div><div class="blog-flow-arrow">干线</div><div class="blog-flow-node">120 Ω<br><small>最远端</small></div></div></div><div class="blog-flow"><div class="blog-flow-col"><div class="blog-flow-node warn">不要：主控当星型中心，向每台从机拉一根长分支</div><div class="blog-flow-down">分支点反射，终端电阻没有唯一的两个端点</div></div></div><p>两端各一只 120 Ω，断电后 CANH–CANL 约 60 Ω。中间节点不要再加终端。1 Mbit/s 时支线宜 ≤ 0.3 m，干线经验长度约 25 m；500 kbit/s 时干线约 100 m，支线尽量 ≤ 1 m。设备离干线远，就把干线拐过去，不要拉长支线。</p><h2 id="can-id" tabindex="-1">CAN ID <a class="header-anchor" href="#can-id" aria-label="Permalink to &quot;CAN ID&quot;">​</a></h2><p>11 位 ID 是 <code>0x000</code>–<code>0x7FF</code>，29 位是 <code>0x00000000</code>–<code>0x1FFFFFFF</code>。它是帧的名字和优先级，不是站地址。两个节点不要用同一个 ID 发不同数据，数据场会打出位错误。</p><table tabindex="0"><thead><tr><th>ID</th><th>谁发</th><th>含义</th></tr></thead><tbody><tr><td>0x080</td><td>故障节点</td><td>急停，能压过周期状态</td></tr><tr><td>0x100 / 0x110</td><td>主控</td><td>广播命令 / 点名写参数</td></tr><tr><td>0x201–0x20F</td><td>各从机</td><td>周期状态，低 4 位是节点号</td></tr><tr><td>0x300 以上</td><td>从机</td><td>日志，优先级最低</td></tr></tbody></table><p><code>0x100</code>（<code>001 0000 0000</code>）和 <code>0x180</code>（<code>001 1000 0000</code>）同时发时，第 4 位分出胜负：前者发显性，后者退出。</p><p>只接收 <code>0x200</code>–<code>0x20F</code> 时，掩码用 <code>0x7F0</code>。STM32 写入过滤器高半字要左移 5 位。</p><p>CANopen 把 11 位分成 4 位功能码和 7 位节点号，心跳是 <code>0x700 + 节点号</code>。J1939 的 29 位里，位 28–26 是优先级，位 7–0 是源地址。</p><h2 id="控制器模式" tabindex="-1">控制器模式 <a class="header-anchor" href="#控制器模式" aria-label="Permalink to &quot;控制器模式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>行为</th></tr></thead><tbody><tr><td>正常</td><td>发送、接收、ACK、错误帧</td></tr><tr><td>静默</td><td>只听，ACK 不驱动到总线</td></tr><tr><td>环回</td><td>忽略 ACK 错误，用于自检；CANTX 仍会输出</td></tr><tr><td>静默环回</td><td>内部把 TX 反馈到 RX。不想影响现网时让收发器待机</td></tr></tbody></table><p>环回能通，不能代替正常模式下的双节点测试。</p><h2 id="四种帧" tabindex="-1">四种帧 <a class="header-anchor" href="#四种帧" aria-label="Permalink to &quot;四种帧&quot;">​</a></h2><p>数据帧、远程帧、错误帧、过载帧。远程帧没有数据场，RTR 为隐性。错误主动节点发 6 个显性加 8 个隐性界定符，其他节点叠加上去后显性段常见 6–12 位。过载帧电平相同，但只出现在帧间空间，不增加错误计数。</p><p>标准帧和扩展帧可以共线。基址相同时，先比标准帧的 RTR 和扩展帧的 SRR，标准数据帧在这一位已经获胜。</p><p>经典 CAN 整帧一个波特率，数据 0–8 字节。CAN FD 的 FDF 为隐性；BRS 为隐性时，从该位采样点切到数据段波特率，CRC 界定符再切回，ACK 仍用标称波特率。DLC 9–15 表示 12、16、20、24、32、48、64 字节。数据不超过 16 字节用 CRC-17，更长用 CRC-21。经典节点看到 FD 帧会发错误帧，总线上不能混有关不掉错误的老节点。数据段到 2 Mbit/s 以上要开收发器延迟补偿（TDC）。</p><h2 id="采样点" tabindex="-1">采样点 <a class="header-anchor" href="#采样点" aria-label="Permalink to &quot;采样点&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>N = 1 + BS1 + BS2</span></span>
<span class="line"><span>波特率 = CAN时钟 / [(BRP+1) × N]</span></span>
<span class="line"><span>采样点 = (1 + BS1) / N</span></span></code></pre></div><p>bxCAN 寄存器里的 TS1、TS2 比 TQ 个数小 1。时钟 42 MHz、500 kbit/s：预分频 6，BS1=11，BS2=2，N=14，采样点约 85.7%。≤500 kbit/s 常用约 87.5%，1 Mbit/s 常用约 75%。硬同步发生在 SOF；帧内重同步每次最多调 SJW 个 TQ。</p><p>Bus-Off 是发送错误计数超过 255。最后错误码 3 几乎总是没有 ACK，或波特率完全不对。</p><p><a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">返回目录</a></p>`,29)])])}const C=d(l,[["render",s]]);export{b as __pageData,C as default};
